import{_ as a,c as p,a as n,o as r}from"./app-DskkZLMv.js";const c={};function i(d,e){return r(),p("div",null,e[0]||(e[0]=[n('<blockquote><p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。 欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p></blockquote><h1 id="_2026-11-09-资讯日报" tabindex="-1"><a class="header-anchor" href="#_2026-11-09-资讯日报"><span>2026-11-09 资讯日报</span></a></h1><h2 id="新闻资讯" tabindex="-1"><a class="header-anchor" href="#新闻资讯"><span>新闻资讯</span></a></h2><h3 id="iclr-2027四万份评审中位数仅2分" tabindex="-1"><a class="header-anchor" href="#iclr-2027四万份评审中位数仅2分"><span>ICLR 2027四万份评审中位数仅2分</span></a></h3><p>ICLR 2027首轮40458份评审中位数仅2/4；多份文本被检测为有91%至93%概率由AI生成。</p><p>投稿趋势：Agent、推理效率和世界模型最热</p><p>新焦点：RSI让模型递归改进自身</p><p>评分偏好：世界行动模型和潜在推理更高<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MTYzMzMxMA==&amp;chksm=c3a12397c794e150c0eba7c173b317d56206460673cf248b7836fc001c268319e283b32bf14b&amp;idx=1&amp;mid=2247513501&amp;sn=73f63affbd3e76cfa22f062e3b88229f" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="deepseek-harness月访问量暴涨14倍" tabindex="-1"><a class="header-anchor" href="#deepseek-harness月访问量暴涨14倍"><span>DeepSeek Harness月访问量暴涨14倍</span></a></h3><p>10月，DeepSeek智能体 Harness访问量达1961万，环比增长1467.48%，逼近腾讯WorkBuddy的2439万。</p><p>Claude：访问量12.9亿，增量超ChatGPT</p><p>Meta Muse：访问量增长228.27%</p><p>模型路由：三款产品访问量均下滑<a href="https://mp.weixin.qq.com/s?__biz=MzA5OTM1NjU3OA==&amp;chksm=86044a81c44ae671aeed90ac65807e9465fffb00837dae13efb54653b57b163be3425517dc92&amp;idx=1&amp;mid=2454321395&amp;sn=e0fc514d7924fa038b0f54fcec9cfbc1" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="扣子企业版最晚2026年底停服" tabindex="-1"><a class="header-anchor" href="#扣子企业版最晚2026年底停服"><span>扣子企业版最晚2026年底停服</span></a></h3><p>扣子企业版将最晚2026年底停服，依赖其服务的产品需迁移架构；扣子团队整体并入豆包团队。<a href="https://mp.weixin.qq.com/s?__biz=Mzg5NzgyNTU2Mg==&amp;chksm=c13ae12b2c9f5191e2eb07221918de0ac2c45d63de9a6fe0ddc432b171f6e78785704eef9302&amp;idx=1&amp;mid=2247543969&amp;sn=03f6f47b9fb4db19f09785b096f32cd0" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="anthropic斥资34亿美元买发电机" tabindex="-1"><a class="header-anchor" href="#anthropic斥资34亿美元买发电机"><span>Anthropic斥资34亿美元买发电机</span></a></h3><p>Anthropic采购1.7吉瓦燃气发电机，交易额34亿美元，并被曝最快本月启动IPO。</p><p>交付：近期及未来两年内到货</p><p>用途：为数据中心直接锁定电力</p><p>风险：黑石预警或获垃圾级评级<a href="https://mp.weixin.qq.com/s?__biz=Mzg3MTkxMjYzOA==&amp;chksm=cf1f45593bd34db9e72a9034d81c48993ca2943a8be12c512b3a1ba7921c09dbfdd1184b1659&amp;idx=1&amp;mid=2247520116&amp;sn=3fcf1a2af66c4c0e25ff19f6ec446467" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="csa发布247项ai安全控制" tabindex="-1"><a class="header-anchor" href="#csa发布247项ai安全控制"><span>CSA发布247项AI安全控制</span></a></h3><p>CSA发布AI安全控制矩阵v1.1，含18个控制域、247项控制目标和320个评估问题，覆盖AI全生命周期。</p><p>定位：把风险转成可实施、可审计控制</p><p>Agent：强调工具授权、执行隔离与链路日志</p><p>兼容：可在现有云安全体系上扩展<a href="https://mp.weixin.qq.com/s?__biz=MzAxNjA0MjIzNg==&amp;chksm=82f51f7756e0d0b88cb76ce8e30b66f7f8fd0a74581f61a5b3bd53297f388c7819b471c591ba&amp;idx=1&amp;mid=2650017273&amp;sn=8761b61ee68c55c3980ed95f690c64c5" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="waymo与丰田2027年日本测试" tabindex="-1"><a class="header-anchor" href="#waymo与丰田2027年日本测试"><span>Waymo与丰田2027年日本测试</span></a></h3><p>2027年起，Waymo与丰田将在日本测试并初期运营bZ4X自动驾驶车队，车辆与自动驾驶硬件均在丰田工厂集成。</p><p>制造：从后期改装进入整车生产</p><p>成本：可靠性和停运时间影响运营</p><p>分工：双方共同参与产品定义<a href="https://mp.weixin.qq.com/s?__biz=MzUyODY1NDE1NA==&amp;chksm=fbffbe7b14382355c5f3fe0ff801af256edaf43befb674df9f34d361a2ccc2cb8297f2f16227&amp;idx=1&amp;mid=2247579038&amp;sn=e5f08ed13f04771c95a5b0443582a183" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="英伟达调查期间黄仁勋仍任ceo" tabindex="-1"><a class="header-anchor" href="#英伟达调查期间黄仁勋仍任ceo"><span>英伟达调查期间黄仁勋仍任CEO</span></a></h3><p>英伟达成立独立委员会调查黄仁勋是否成为外国情报行动目标；公司称黄仁勋继续履职，目前无证据显示机密受损。</p><p>国会：要求黄仁勋11月18日闭门说明</p><p>业务：未宣布停售、换帅或产品调整</p><p>进展：调查尚无结论，相关指控未获司法认定<a href="https://mp.weixin.qq.com/s?__biz=MzA3NzMxNTI1MQ==&amp;chksm=869b8a190bf4b977fc8faca75aaac4dd995697f5a4d343d1421ae06da07c6644a0a20bb4feb7&amp;idx=1&amp;mid=2649787306&amp;sn=a83920204968a0c961f03acc278afcc2" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="产品应用" tabindex="-1"><a class="header-anchor" href="#产品应用"><span>产品应用</span></a></h2><h3 id="databricks-genie能读power-bi指标" tabindex="-1"><a class="header-anchor" href="#databricks-genie能读power-bi指标"><span>Databricks Genie能读Power BI指标</span></a></h3><p>Databricks让Genie复用Power BI指标定义，Snowflake推出业务本体预览，避免Agent因选错业务口径算错收入。</p><p>状态：两项本体能力仍处预览阶段</p><p>治理：业务定义变更须负责人审批</p><p>作用：同名指标可按财务、销售区分<a href="https://mp.weixin.qq.com/s?__biz=MzU1NTMyOTI4Mw==&amp;chksm=fa13fd696cab76179ea9cb989e1f31f0e36d913fa8d71198418ef82b3e3935987a5131b77418&amp;idx=1&amp;mid=2247783666&amp;sn=214abdeb0a21719d7609afd0d5bfdae7" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="claude误删教授一年讲义" tabindex="-1"><a class="header-anchor" href="#claude误删教授一年讲义"><span>Claude误删教授一年讲义</span></a></h3><p>芝大教授让Claude改页码，一年讲义和教学大纲被误删，后靠Dropbox全部找回。</p><p>权限：只开放副本所在文件夹</p><p>防误删：设为可读写但不可删除</p><p>恢复：查已删除文件和版本历史<a href="https://mp.weixin.qq.com/s?__biz=MzI3MTA0MTk1MA==&amp;chksm=f07b6ad5848489e8936d3a2c26c95943f5e999ade1659eeb8707da3d6ebe56ff57a1febb888a&amp;idx=2&amp;mid=2652741306&amp;sn=ca3a968dc876193340e7e0975c1248e5" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="高通6g原型机测试峰值约14g" tabindex="-1"><a class="header-anchor" href="#高通6g原型机测试峰值约14g"><span>高通6G原型机测试峰值约14G</span></a></h3><p>全球首台符合3GPP最新定义的6G终端原型机亮相，互通测试峰值约14G；首个6G标准版本预计2029年完成。</p><p>AI用户：2030年81%手机用户将使用AI</p><p>边缘算力：未来五年更多推理靠近终端</p><p>安全：首版6G计划支持后量子密码<a href="https://mp.weixin.qq.com/s?__biz=Mzg4MjYyMzUyNw==&amp;chksm=ce13875c8ebd49b772f755d29090af6daec319ce4707f46a1e83a8d8bbddedbda398e2b6ff18&amp;idx=1&amp;mid=2247521541&amp;sn=45c3d4027fc6640dadd241e601292745" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="腾讯databuddy拆解企业问数架构" tabindex="-1"><a class="header-anchor" href="#腾讯databuddy拆解企业问数架构"><span>腾讯DataBuddy拆解企业问数架构</span></a></h3><p>腾讯 DataBuddy 用业务语义层固定指标口径，让大模型先生成语义 SQL，再编译为物理 SQL，减少企业问数中的歧义与幻觉。</p><p>架构：工程、治理、分析三类 Agent</p><p>语义层：统一本体、指标与血缘</p><p>自建方案：语义服务加受控工具<a href="https://mp.weixin.qq.com/s?__biz=Mzk1NzQ1ODk5NQ==&amp;chksm=c2e285b43dc9850e47bd671e1752c196692f9387b43a94bd425fecd242936d13f4d127880348&amp;idx=1&amp;mid=2247526848&amp;sn=8f97774884d34b8c2d94dcc9452060e2" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="李沐团队全双工模型160毫秒一轮" tabindex="-1"><a class="header-anchor" href="#李沐团队全双工模型160毫秒一轮"><span>李沐团队全双工模型160毫秒一轮</span></a></h3><p>李沐团队的 Higgs Realtime Duplex 以 160毫秒窗口同时听说和调用工具，基于 45B MoE；目前开放候补名单，即将上线。</p><p>成本：每分钟共用2.6K至5K tokens</p><p>上下文：仅保留最近5分钟完整音视频</p><p>评测：Big Bench Audio获98.9分<a href="https://mp.weixin.qq.com/s?__biz=MzIyNjM2MzQyNg==&amp;chksm=e920cfa2beea2278f1de6481825bc7395904facd53ccfcc406cb616b3c7f7a2c4aa7b8980d4c&amp;idx=1&amp;mid=2247729818&amp;sn=7ffee68e5b08c11ec6b11ec1b80c4a2e" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="推荐文章" tabindex="-1"><a class="header-anchor" href="#推荐文章"><span>推荐文章</span></a></h2><h3 id="智能知识-只靠rsi到不了agi" tabindex="-1"><a class="header-anchor" href="#智能知识-只靠rsi到不了agi"><span>智能知识：只靠RSI到不了AGI</span></a></h3><p>智能知识认为，RSI（模型自我改进）只能用尽现有能力，无法产生新智能；走向AGI仍依赖专家经验转化的高质量人类数据。</p><p>数据标准：质量已比数量和多样性重要</p><p>训练难点：任务设计和评分依赖专家判断</p><p>行业现状：模型厂外部数据采购仍供不应求<a href="https://mp.weixin.qq.com/s?__biz=MzkyNjU2ODM2NQ==&amp;chksm=c39fa796d7f26ee6f4f791213aaebcbed9d066a0d8528da4960cde70832f7602a2c5f0fe515e&amp;idx=1&amp;mid=2247635158&amp;sn=b592e2b9ea19991f80c32ec809cb6e61" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="开源动态" tabindex="-1"><a class="header-anchor" href="#开源动态"><span>开源动态</span></a></h2><h3 id="lobehub智能体任务通过率70" tabindex="-1"><a class="header-anchor" href="#lobehub智能体任务通过率70"><span>LobeHub智能体任务通过率70%</span></a></h3><p>开源AI协作平台LobeHub可让Agent拆任务、写代码和验收；软件工程测试通过率70%，单次成功成本中位数1.68美元。</p><p>研发实测：个人体感效率提升3至5倍</p><p>长任务：连续运行2天3小时，拆出60项</p><p>使用方式：源码已上GitHub，可自行部署<a href="https://mp.weixin.qq.com/s?__biz=MzIzNjc1NzUzMw==&amp;chksm=e9cca3da4d43a2447908e4c34409d3beb93b53eed8b7cde1dd20925b8f3fe9cf6135b93c9fbd&amp;idx=1&amp;mid=2247940486&amp;sn=8678d2fd2fb6c737c7acfdcfd4733b86" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="deepseek小更新agent榜涨11-1分" tabindex="-1"><a class="header-anchor" href="#deepseek小更新agent榜涨11-1分"><span>DeepSeek小更新Agent榜涨11.1分</span></a></h3><p>DeepSeek-V4.1-Flash-1017 已上线网页、App 和 API，价格不变且 MIT 开源；Agent 榜最高涨11.1分，但换 Agent 框架可差 8.7 分。</p><p>能力：工具榜领先，裸考落后 Opus 13.7 分</p><p>架构：每个 token 的 KV 缓存压至 890 字节</p><p>成本：谷时每任务 0.0173 美元，峰时翻倍<a href="https://mp.weixin.qq.com/s?__biz=MzU0MDQ1NjAzNg==&amp;chksm=fa27d6e86cd01abae2c2960f5727c1fdcc36fc0008939d0325252f0845233d0a32b1627fa914&amp;idx=1&amp;mid=2247589722&amp;sn=892f0f3d9177e7e3bc882fb644995420" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h2 id="算法论文" tabindex="-1"><a class="header-anchor" href="#算法论文"><span>算法论文</span></a></h2><h3 id="英伟达短上下文最高省233-3倍" tabindex="-1"><a class="header-anchor" href="#英伟达短上下文最高省233-3倍"><span>英伟达短上下文最高省233.3倍</span></a></h3><p>英伟达研究称，Agent用短上下文配合状态压缩，准确率基本不降，成本最高节省233.3倍。</p><p>长上下文：解码成本增至3.6～7倍</p><p>长程任务：22组中不到5组掉点超2%</p><p>RULER：召回率62.5%升至95.7%<a href="https://mp.weixin.qq.com/s?__biz=Mzk0MTYzMzMxMA==&amp;chksm=c3354b8bcf8f51d4f37e54740340d38fc123e68239f827e1d837ba418cef539c7aa951259a05&amp;idx=2&amp;mid=2247513501&amp;sn=f1bb7aad31565c07eb45d281db8beb8b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="英伟达tacitvla动作提速3-4倍" tabindex="-1"><a class="header-anchor" href="#英伟达tacitvla动作提速3-4倍"><span>英伟达TacitVLA动作提速3.4倍</span></a></h3><p>英伟达等提出视觉语言动作模型 TacitVLA，让机器人先行动、同步写推理文本，延迟最多降低3.4倍，成功率与显式推理相当。</p><p>训练：仅修改注意力掩码，无需额外模型</p><p>记忆任务：RMBench成功率达77.5%</p><p>速度：单张H100输出动作仅需147毫秒<a href="https://mp.weixin.qq.com/s?__biz=MzA3MzI4MjgzMw==&amp;chksm=85625b5bcc8b79615ea7bfdfe8ed77c7ffcd1cecf36afaf69ff5db5a2a6fe3b165a02807402c&amp;idx=3&amp;mid=2651072888&amp;sn=75cf566a70af17c8a5cfa30d459aab8b" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="gpt-6-astra改权重未提升数学能力" tabindex="-1"><a class="header-anchor" href="#gpt-6-astra改权重未提升数学能力"><span>GPT-6 Astra改权重未提升数学能力</span></a></h3><p>对照实验显示，Qwen3.5-0.8B关闭思考模式得分48.95%，高于Astra改权重后的48.1%。</p><p>数学提升：主要来自减少重复循环</p><p>能力测试：知识和角色写入均失败</p><p>技能内化：Astra答对1题，超网络7题<a href="https://mp.weixin.qq.com/s?__biz=MzI4MDYzNzg4Mw==&amp;chksm=ea0f702c8e9fbe2c1aa8d50b86cd52845479be74ef136ff6a9462842a73f2cb396ea9120efe7&amp;idx=3&amp;mid=2247582098&amp;sn=4da275408e76f63a77ff77696f902fca" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="claude记忆让任务奖励升至0-83" tabindex="-1"><a class="header-anchor" href="#claude记忆让任务奖励升至0-83"><span>Claude记忆让任务奖励升至0.83</span></a></h3><p>Anthropic 实验显示，Claude Opus 5 加入跨会话记忆后，任务平均奖励从约0.56升至0.83；但旧经验跨场景复用可让不安全动作率升至35%～81%。</p><p>分层：记录、笔记、知识页与启动索引分工</p><p>组织：知识页结合搜索得分达61%</p><p>边界：高风险行动不能把记忆当授权<a href="https://mp.weixin.qq.com/s?__biz=MzAxMjc3MjkyMg==&amp;chksm=82913c40875d7d320df9fb30593daa445406f6cf97b4b000e884aa5540275126dda6aaa0448a&amp;idx=2&amp;mid=2648434990&amp;sn=e419a5fa9af78091e0c49a5959a14782" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><h3 id="anthropic-ai可接手38-科研工时" tabindex="-1"><a class="header-anchor" href="#anthropic-ai可接手38-科研工时"><span>Anthropic：AI可接手38%科研工时</span></a></h3><p>Anthropic分析超20万次Claude科研会话：按当前能力普及使用，AI可接手科研工时中位数38%，统计学产出估算可达2.02倍。</p><p>使用：计算机科学占32.7%科研代码对话</p><p>短板：提假设与数据采集使用最少</p><p>情景：非实操任务全自动时最高16倍<a href="https://mp.weixin.qq.com/s?__biz=MzIwOTA1MDAyNA==&amp;chksm=8eda1e8328959106b4bf094e9812bef68565b8553547a8c0f013dbf50800f9206b82134b7264&amp;idx=2&amp;mid=2650057407&amp;sn=8c6b26d009f94af29d1342ba58355108" target="_blank" rel="noopener noreferrer">&gt;阅读原文</a></p><p style="text-align:center;"><img id="weixin_qr" src="https://meikan-public-images.oss-cn-beijing.aliyuncs.com/imeikan/assets/2025-05-18234303-hub.png" style="max-width:800px;object-fit:cover;"></p><p><a href="https://aireadinghub.com/" target="_blank" rel="noopener noreferrer">官网：www.AiReadingHub.com</a></p>',106)]))}const s=a(c,[["render",i]]),l=JSON.parse('{"path":"/posts/2026-11-09.html","title":"AI日报：ICLR 2027四万份评审中位数仅2分; DeepSeek Harness月访问量暴涨14倍; 扣子企业版最晚2026年底停服","lang":"zh-CN","frontmatter":{"date":"2026-11-09T00:00:00.000Z","title":"AI日报：ICLR 2027四万份评审中位数仅2分; DeepSeek Harness月访问量暴涨14倍; 扣子企业版最晚2026年底停服"},"headers":[{"level":2,"title":"新闻资讯","slug":"新闻资讯","link":"#新闻资讯","children":[{"level":3,"title":"ICLR 2027四万份评审中位数仅2分","slug":"iclr-2027四万份评审中位数仅2分","link":"#iclr-2027四万份评审中位数仅2分","children":[]},{"level":3,"title":"DeepSeek Harness月访问量暴涨14倍","slug":"deepseek-harness月访问量暴涨14倍","link":"#deepseek-harness月访问量暴涨14倍","children":[]},{"level":3,"title":"扣子企业版最晚2026年底停服","slug":"扣子企业版最晚2026年底停服","link":"#扣子企业版最晚2026年底停服","children":[]},{"level":3,"title":"Anthropic斥资34亿美元买发电机","slug":"anthropic斥资34亿美元买发电机","link":"#anthropic斥资34亿美元买发电机","children":[]},{"level":3,"title":"CSA发布247项AI安全控制","slug":"csa发布247项ai安全控制","link":"#csa发布247项ai安全控制","children":[]},{"level":3,"title":"Waymo与丰田2027年日本测试","slug":"waymo与丰田2027年日本测试","link":"#waymo与丰田2027年日本测试","children":[]},{"level":3,"title":"英伟达调查期间黄仁勋仍任CEO","slug":"英伟达调查期间黄仁勋仍任ceo","link":"#英伟达调查期间黄仁勋仍任ceo","children":[]}]},{"level":2,"title":"产品应用","slug":"产品应用","link":"#产品应用","children":[{"level":3,"title":"Databricks Genie能读Power BI指标","slug":"databricks-genie能读power-bi指标","link":"#databricks-genie能读power-bi指标","children":[]},{"level":3,"title":"Claude误删教授一年讲义","slug":"claude误删教授一年讲义","link":"#claude误删教授一年讲义","children":[]},{"level":3,"title":"高通6G原型机测试峰值约14G","slug":"高通6g原型机测试峰值约14g","link":"#高通6g原型机测试峰值约14g","children":[]},{"level":3,"title":"腾讯DataBuddy拆解企业问数架构","slug":"腾讯databuddy拆解企业问数架构","link":"#腾讯databuddy拆解企业问数架构","children":[]},{"level":3,"title":"李沐团队全双工模型160毫秒一轮","slug":"李沐团队全双工模型160毫秒一轮","link":"#李沐团队全双工模型160毫秒一轮","children":[]}]},{"level":2,"title":"推荐文章","slug":"推荐文章","link":"#推荐文章","children":[{"level":3,"title":"智能知识：只靠RSI到不了AGI","slug":"智能知识-只靠rsi到不了agi","link":"#智能知识-只靠rsi到不了agi","children":[]}]},{"level":2,"title":"开源动态","slug":"开源动态","link":"#开源动态","children":[{"level":3,"title":"LobeHub智能体任务通过率70%","slug":"lobehub智能体任务通过率70","link":"#lobehub智能体任务通过率70","children":[]},{"level":3,"title":"DeepSeek小更新Agent榜涨11.1分","slug":"deepseek小更新agent榜涨11-1分","link":"#deepseek小更新agent榜涨11-1分","children":[]}]},{"level":2,"title":"算法论文","slug":"算法论文","link":"#算法论文","children":[{"level":3,"title":"英伟达短上下文最高省233.3倍","slug":"英伟达短上下文最高省233-3倍","link":"#英伟达短上下文最高省233-3倍","children":[]},{"level":3,"title":"英伟达TacitVLA动作提速3.4倍","slug":"英伟达tacitvla动作提速3-4倍","link":"#英伟达tacitvla动作提速3-4倍","children":[]},{"level":3,"title":"GPT-6 Astra改权重未提升数学能力","slug":"gpt-6-astra改权重未提升数学能力","link":"#gpt-6-astra改权重未提升数学能力","children":[]},{"level":3,"title":"Claude记忆让任务奖励升至0.83","slug":"claude记忆让任务奖励升至0-83","link":"#claude记忆让任务奖励升至0-83","children":[]},{"level":3,"title":"Anthropic：AI可接手38%科研工时","slug":"anthropic-ai可接手38-科研工时","link":"#anthropic-ai可接手38-科研工时","children":[]}]}],"git":{"updatedTime":1794227372000,"contributors":[{"name":"GitHub Actions","username":"","email":"actions@github.com","commits":1}],"changelog":[{"hash":"fd5c5db9d44a5ca1f26b3d71d9979508a10a59a3","time":1794227372000,"email":"actions@github.com","author":"GitHub Actions","message":"Auto-commit generated files on 2026-11-09T12:29:31.974Z"}]},"filePathRelative":"posts/2026-11-09.md","excerpt":"<blockquote>\\n<p>All in AI，看见未来。 每天精选最值得读的AI文章，帮你筛掉时代的噪音。 以简讯见广度，以深读见洞察。 技术、趋势、思考，一站式掌握AI世界。\\n欢迎关注公众号「AI Reading Hub」，获取更多AI资讯和技术文章。</p>\\n</blockquote>\\n<h1>2026-11-09 资讯日报</h1>\\n<h2>新闻资讯</h2>\\n<h3>ICLR 2027四万份评审中位数仅2分</h3>\\n<p>ICLR 2027首轮40458份评审中位数仅2/4；多份文本被检测为有91%至93%概率由AI生成。</p>\\n<p>投稿趋势：Agent、推理效率和世界模型最热</p>"}');export{s as comp,l as data};
